for s,t in zip(['da1','daO','da5','da4','da3','da2'],['daO','da5','da4','da3','da2','da1']):b(s,t)
for s,t,d in [('da1','m10O','down'),('da5','da5Me','down'),('da3','daN','down'),('da2','da2OH','up')]:b(s,t,1,d)
for t in ['daNMe1','daNMe2']:b('daN',t)
# cladinose ring
for name,element,x,y in [('cl1','C',731,887),('clO','O',835,943),('cl5','C',835,1063),('cl5Me','C',892,1093),('cl4','C',731,1124),('cl4OH','O',731,1228),('cl3','C',627,1064),('cl3Me','C',584,1147),('cl3OMeO','O',509,1063),('cl3OMeC','C',412,1063),('cl2','C',627,943)]:a(name,element,x,y)
for s,t in zip(['cl1','clO','cl5','cl4','cl3','cl2'],['clO','cl5','cl4','cl3','cl2','cl1']):b(s,t)
