Chem.MolToMolFile(m,'/tmp/best.mol',confId=idx)
with open('answer.xyz','w') as file:
 file.write(f'{m.GetNumAtoms()}\nerythromycin A, stereospecific MMFF94s optimized structure\n')
 conf=m.GetConformer(idx)
 for atom in m.GetAtoms():
  p=conf.GetAtomPosition(atom.GetIdx());file.write(f'{atom.GetSymbol():2s} {p.x: .8f} {p.y: .8f} {p.z: .8f}\n')
